INSERT INTO public.areas (area_id, nom_area) VALUES
    (1, 'Ingeniería y Ciencias Físico Matemáticas'),
    (2, 'Ciencias Médico Biológicas'),
    (3, 'Ciencias Sociales y Administrativas');
INSERT INTO public.carreras (carrera_id, area_id, nom_carrera, origina_objetivo, objetivo, pregunta_objetivo) VALUES
    (1, 1, 'Ingeniería Aeronáutica', 'Formar Ingenieros con los conocimientos fundamentales en las diversas disciplinas de la Ingeniería Aeronáutica, que les permitan desempeñarse con eficiencia en los campos de: investigación, diseño, construcción, instalación, operación, mantenimiento y administración de los sistemas de aeronaves, así como la operación de la infraestructura de soporte de las empresas e instituciones del sector transporte aéreo, con la capacidad de administrar los recursos humanos, tecnológicos y financieros dispuestos en su campo de acción para el desarrollo tecnológico, económico y social.', 'Prepararse para diseñar, operar y mantener sistemas relacionados con la aviación, asi como organizar los recursos necesarios para que funcionen adecuadamente.', '¿Te interesa diseñar, operar y mantener sistemas aeronáuticos, además de administrar recursos para su funcionamiento?'),
    (2, 1, 'Ingeniería Ambiental', 'Formar ingenieros que atiendan a las demandas y necesidades de la Administración Pública iniciativa privada y la sociedad en materia de ambiente con capacidad de administrar diseñar construir y operar sistemas para la prevención mitigación o eliminación de contaminantes en suelo agua y aire Además de participar en la gestión evaluación y planeación de la sustentabilidad de los recursos naturales en forma ética y eficiente.', 'Aprender a buscar soluciones a problemas de contaminación, diseñar y gestionar sistemas para prevenir, mitigar o eliminar contaminantes y promover el uso sustentable de los recursos naturales.', '¿Te interesa diseñar soluciones para prevenir o reducir la contaminación y gestionar de manera sustentable los recursos naturales?'),
    (3, 1, 'Ingeniería Biomédica', 'Formar profesionista en Ingeniería Biomédica con sentido de responsabilidad actitudes y valores que contribuyan al desarrollo tecnológico la investigación la extensión y a incrementar la eficiencia de los procesos de atención a la salud mediante la conjunción de las áreas médicas las ciencias exactas la administración y la conservación hospitalaria.', 'Aprender a integrar conocimientos de ingeniería, ciencias exactas y salud para desarrollar tecnología y mejorar procesos de atención sanitaria.', '¿Te interesa combinar tecnología, ingeniería y ciencias de la salud para mejorar equipos o procesos de atención médica?'),
    (4, 1, 'Ingeniería Biónica', 'Formar ingenieros cuya misión es la de diseñar desarrollar y producir dispositivos artificiales que posean un comportamiento y desempeño morfológico y/o funcional semejante al de órganos o sistemas biológicos. La Ingeniería Biónica se concibe como el conjunto de conocimientos interdisciplinarios entre la electrónica y la biología cuyo propósito es la creación de sistemas artificiales para reproducir las características y la estructura de organismos vivos.', 'Diseñar y desarrollar dispositivos artificiales inspirados en estructuras y funciones de organismos vivos.', '¿Te interesa diseñar dispositivos tecnológicos que imiten funciones o características de los seres vivos?'),
    (5, 1, 'Ingeniería Bioquímica', 'El programa académico de Ingeniería Bioquímica tiene como finalidad formar profesionistas competentes en los ámbitos de Bioprocesos, Bioingeniería de alimentos, Bioingeniería Ambiental e Ingeniería Metabólica, con valores éticos, liderazgo y responsabilidad con el entorno, que le permitan responder a las necesidades de la sociedad y desarrollo sustentable de la nación.', 'Aplicar conocimientos de bioprocesos, alimentos, ambiente e ingeniería metabólica para resolver necesidades sociales de manera sustentable.', '¿Te interesa aplicar procesos biológicos y químicos para desarrollar soluciones en alimentos, ambiente o producción sustentable?'),
    (6, 1, 'Ingeniería Biotecnológica', 'Formar profesionistas de alto nivel en el campo de la Ingeniería Biotecnológica que contribuyan al bienestar y desarrollo tecnológico nacional mediante la aplicación y generación de conocimientos que se vinculen a las necesidades de los sectores productivo y social.', 'Utilizar y generar conocimientos biotecnológicos para atender necesidades de los sectores productivo y social.', '¿Te interesa utilizar la biotecnología para desarrollar soluciones que atiendan necesidades sociales o productivas?'),
    (7, 1, 'Ingeniería Civil', 'Formar profesionistas en Ingeniería Civil, con conocimientos sólidos, tecnológicos y humanistas en las áreas disciplinares que le permitan desempeñarse satisfactoriamente en el ámbito profesional, con conocimientos, habilidades, actitudes y valores en la planeación, diseño, construcción, operación, mantenimiento y administración de obras de infraestructura, incorporando aspectos del desarrollo sustentable de manera explícita, en beneficio de la sociedad con sentido ético y deontológico para contribuir al desarrollo de la nación.', 'Diseñar,planear, construir, operar y administrar obras de infraestructura incorporando criterios de sustentabilidad.', '¿Te interesa planear y desarrollar obras de infraestructura considerando su funcionamiento, administración y impacto sustentable?'),
    (8, 1, 'Ingeniería Eléctrica', 'Formar profesionales capaces de planear, proyectar, diseñar, innovar, controlar, instalar, construir, coordinar, dirigir, mantener y administrar equipos y sistemas, aparatos y dispositivos destinados a la generación, transformación y aprovechamiento de la energía eléctrica en todas sus aplicaciones, así como operar equipos y materiales eléctricos tomando en cuenta su interrelación con los sistemas de potencia distribución y utilización; Además de participar en la construcción, mantenimiento, conservación y administración de la planta productiva, con una visión integral del desarrollo social, económico e industrial del país.', 'Planear, diseñar, construir, operar, mantener y administrar equipos y sistemas de generación y aprovechamiento de energía eléctrica.', '¿Te interesa diseñar y administrar sistemas eléctricos y participar en su instalación, operación y mantenimiento?'),
    (9, 1, 'Ingeniería en Alimentos', 'Formar profesionales íntegramente, con una sólida formación y con conocimientos tecnológicos en el campo de la Ingeniería en Alimentos, que contribuyan a resolver problemas y plantear nuevas alternativas para satisfacer las necesidades que en esta área se presenten en los sectores productivo y social. Generar y vincular, a través de las actividades de investigación y desarrollo, conocimientos, bienes y servicios tecnológicos y biotecnológicos en Ingeniería de Alimentos, que coadyuven en la solución de los problemas nacionales del sector del país. Difundir la cultura tecnológica en el campo de la Ingeniería de Alimentos, accediendo los conocimientos a todos los niveles científicos, educativos productivos y sociales del país. Vincular las actividades de los estudios e investigaciones en Ingeniería de Alimentos en los sectores productivos del país e instituciones normativas, a fin de establecer una integración vertical que permita tener participación en la solución de los problemas nacionales en el área.
